macro_rules! deps {
    () => {
        IoctlOutput!();
        Opcode!();
        Result!();
    };
}

macro_rules! Ioctl {
    () => {
        deps!();
        # [doc = " A trait defining the properties of an `ioctl` command."] # [doc = ""] # [doc = " Objects implementing this trait can be passed to [`ioctl`] to make an"] # [doc = " `ioctl` call. The contents of the object represent the inputs to the"] # [doc = " `ioctl` call. The inputs must be convertible to a pointer through the"] # [doc = " `as_ptr` method. In most cases, this involves either casting a number to a"] # [doc = " pointer, or creating a pointer to the actual data. The latter case is"] # [doc = " necessary for `ioctl` calls that modify userspace data."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " This trait is unsafe to implement because it is impossible to guarantee"] # [doc = " that the `ioctl` call is safe. The `ioctl` call may be proprietary, or it"] # [doc = " may be unsafe to call in certain circumstances."] # [doc = ""] # [doc = " By implementing this trait, you guarantee that:"] # [doc = ""] # [doc = "  - The `ioctl` call expects the input provided by `as_ptr` and produces the"] # [doc = "    output as indicated by `output`."] # [doc = "  - That `output_from_ptr` can safely take the pointer from `as_ptr` and"] # [doc = "    cast it to the correct type, *only* after the `ioctl` call."] # [doc = "  - That the return value of `opcode` uniquely identifies the `ioctl` call."] # [doc = "  - That, for whatever platforms you are targeting, the `ioctl` call is safe"] # [doc = "    to make."] # [doc = "  - If `IS_MUTATING` is false, that no userspace data will be modified by"] # [doc = "    the `ioctl` call."] pub unsafe trait Ioctl { # [doc = " The type of the output data."] # [doc = ""] # [doc = " Given a pointer, one should be able to construct an instance of this"] # [doc = " type."] type Output ; # [doc = " Does the `ioctl` mutate any data in the userspace?"] # [doc = ""] # [doc = " If the `ioctl` call does not mutate any data in the userspace, then"] # [doc = " making this `false` enables optimizations that can make the call"] # [doc = " faster. When in doubt, set this to `true`."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " This should only be set to `false` if the `ioctl` call does not mutate"] # [doc = " any data in the userspace. Undefined behavior may occur if this is set"] # [doc = " to `false` when it should be `true`."] const IS_MUTATING : bool ; # [doc = " Get the opcode used by this `ioctl` command."] # [doc = ""] # [doc = " There are different types of opcode depending on the operation. See"] # [doc = " documentation for [`opcode`] for more information."] fn opcode (& self) -> Opcode ; # [doc = " Get a pointer to the data to be passed to the `ioctl` command."] # [doc = ""] # [doc = " See trait-level documentation for more information."] fn as_ptr (& mut self) -> * mut c :: c_void ; # [doc = " Cast the output data to the correct type."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The `extract_output` value must be the resulting value after a"] # [doc = " successful `ioctl` call, and `out` is the direct return value of an"] # [doc = " `ioctl` call that did not fail. In this case `extract_output` is the"] # [doc = " pointer that was passed to the `ioctl` call."] unsafe fn output_from_ptr (out : IoctlOutput , extract_output : * mut c :: c_void ,) -> Result < Self :: Output > ; }
    };
}

Ioctl!()